// Mobile-only support additions: incoming alert, team availability, mobile admin, recurring, link git, emergency fix, route-to-dev.
import { STATUS, TICKET_STATUS, pillStyle, tagStyle, priColor } from './proto-core.js';
import * as MOD from './proto-modals.js';
import * as SUP from './proto-support.js';

const note = (text, tone) => ({ text, style: tone === 'warn' ? 'background:#fbf6ea;border:1px solid #f0d9b0;border-radius:8px;padding:9px 12px;color:#7a5410;font-size:12px' : tone === 'danger' ? 'background:#fbe9e3;border:1px solid #f0c9bd;border-radius:8px;padding:9px 12px;color:#a8321f;font-size:12px' : 'background:#fafaf8;border:1px solid #e4e4e0;border-radius:8px;padding:9px 12px;color:#4a4b4e;font-size:12px' });

export function linkGit(A, taskId) { const t = A.T(taskId); const p = A.P(t.projectId); A.modal({ title: 'Link GitHub work', subtitle: `${t.id} · ${p.repo}`, fields: [{ key: 'kind', type: 'seg', label: 'What', options: ['Branch', 'Commit', 'Pull request'].map(v => ({ value: v, label: v })), value: 'Pull request' }, { key: 'ref', type: 'text', label: 'Reference', full: true, value: `${t.id}-${t.title.toLowerCase().replace(/[^a-z0-9]+/g, '-').slice(0, 16)}`, help: 'Anything containing the task ID links automatically via the GitHub App' }], actions: [{ label: 'Cancel', kind: 'secondary', onClick: () => A.closeModal() }, { label: 'Link', kind: 'dark', onClick: () => { const k = A.val('kind'); if (k === 'Pull request') { t.pr = t.pr || { num: 240 + A.D.counter.task, state: 'Open', merged: false, branch: A.val('ref') }; t.checks = t.checks || { build: 'running', lint: 'pass', unit: 'pending', api: 'pending', security: 'pending', e2e: 'pending' }; } else t.gitRef = A.val('ref'); t.comments.push({ by: A.me.id, at: '04/09 ' + A.now(), body: `Linked ${k.toLowerCase()} ${A.val('ref')}`, pub: false }); A.audit('GITHUB', `${t.id} linked ${k} ${A.val('ref')}`); A.save(); A.closeModal(); A.toast(`${k} linked`); } }] }); }
export function approveEmergency(A, tkId) { const tk = A.TK(tkId); A.modal({ title: 'Approve emergency production fix', subtitle: `${tk.id} · incident`, notes: [note('Skips scheduled release; still requires QA smoke on production afterwards. Fully audited with your name and reason.', 'danger')], fields: [{ key: 'reason', type: 'area', label: 'Reason (required)', full: true }], actions: [{ label: 'Cancel', kind: 'secondary', onClick: () => A.closeModal() }, { label: 'Approve emergency fix', kind: 'danger', onClick: () => { const r = (A.val('reason') || '').trim(); if (!r) return A.toast('A reason is required'); tk.emergencyApproved = { by: A.me.id, at: '04/09 ' + A.now(), reason: r }; tk.taskIds.forEach(id => { const t = A.T(id); if (t) t.emergency = true; }); A.audit('APPROVAL', `Emergency fix approved for ${tk.id} — ${r}`); A.notify(tk.assignedTo, `Emergency fix approved for ${tk.id} — hotfix path open`, 'ticketDetail', tk.id); A.save(); A.closeModal(); A.toast('Emergency fix approved — audited'); } }] }); }
export function routeToDev(A, tkId) { const tk = A.TK(tkId); A.modal({ title: 'Route to developer', subtitle: `${tk.id} · hands this technical issue to automatic routing`, fields: [{ key: 'type', type: 'select', label: 'Technical type', options: ['Bug', 'Outage', 'Performance', 'Access issue'].map(v => ({ value: v, label: v })), value: 'Bug' }, { key: 'module', type: 'select', label: 'Module', options: ['General', 'Auth', 'Invoicing', 'Import', 'Reports', 'Scanning', 'Payments', 'Printing', 'Leave', 'Payroll'].map(v => ({ value: v, label: v })), value: tk.module || 'General' }], actions: [{ label: 'Cancel', kind: 'secondary', onClick: () => A.closeModal() }, { label: 'Route automatically', kind: 'primary', onClick: () => { tk.type = A.val('type'); tk.module = A.val('module'); tk.assignments = tk.assignments || []; SUP.route(A, tk); A.save(); A.closeModal(); A.toast(tk.assignedTo ? `Routed to ${A.name(tk.assignedTo)} — ${tk.routedNote}` : 'No developer available — escalated'); } }] }); }
export function requestCallback(A, tkId) { const tk = A.TK(tkId); A.modal({ title: 'Request a call', subtitle: 'We call you through our support line — your number stays private', fields: [{ key: 'when', type: 'seg', label: 'When', options: [{ value: 'now', label: 'As soon as possible' }, { value: 'sched', label: 'Schedule' }], value: 'now' }, { key: 'slot', type: 'select', label: 'Preferred slot', options: ['Today 14:00–15:00', 'Today 16:00–17:00', 'Tomorrow 10:00–11:00'].map(v => ({ value: v, label: v })), value: 'Today 14:00–15:00' }], actions: [{ label: 'Cancel', kind: 'secondary', onClick: () => A.closeModal() }, { label: 'Request call', kind: 'primary', onClick: () => { const o = SUP.owner(A, tk.projectId); const to = tk.assignedTo || SUP.today(A, tk.projectId) || o.primary; A.D.callbacks.unshift({ id: 'CB-' + (A.D.counter.callback++), ticketId: tk.id, orgId: tk.orgId, requestedAt: '04/09 ' + A.now(), due: A.val('when') === 'now' ? 'ASAP' : A.val('slot'), assignedTo: to, status: 'Scheduled' }); tk.replies.push({ by: A.me.id, at: '04/09 ' + A.now(), body: `Requested a call (${A.val('when') === 'now' ? 'as soon as possible' : A.val('slot')}).`, pub: true }); A.notify(to, `${tk.id}: client requested a callback (${A.val('when') === 'now' ? 'ASAP' : A.val('slot')})`, 'ticketDetail', tk.id); A.save(); A.closeModal(); A.toast('We will call you from the support line'); } }] }); }
export function incomingAlert(A) { const me = A.me; const dev = ['developer', 'senior'].includes(A.S.roleKey) ? me.id : 'u_priya'; const org = A.O('o_acme'); const id = `${org.code}-${String(A.D.counter.ticket++).padStart(4, '0')}`; const tk = { id, orgId: 'o_acme', projectId: 'p_crm', requesterId: 'u_sunita', type: 'Bug', priority: 'High', title: 'Customer import fails with GSTIN error', desc: 'Import stops at row 40 with "invalid GSTIN" although the value is correct.', status: 'NEW', assignedTo: null, team: null, respondBy: '2h', resolveBy: '1 day', firstResponse: null, source: 'Mobile app', raised: '04/09 ' + A.now(), replies: [{ by: 'u_sunita', at: '04/09 ' + A.now(), body: 'Import stops at row 40 with an invalid GSTIN error although the value is correct.', pub: true }], taskIds: [], resolution: '', module: 'Import', version: '2.3.0', assignments: [], calls: [], escalationLevel: 0, nextUpdate: 'in 4h' }; A.D.tickets.unshift(tk); SUP.route(A, tk); if (tk.assignedTo !== dev && tk.status === 'AUTO_ASSIGNED') { tk.assignments.push({ kind: 'REASSIGN', from: tk.assignedTo, to: dev, at: '04/09 ' + A.now(), reason: 'Prototype: push demo to current user' }); tk.assignedTo = dev; } A.save(); const sim = SUP.similar(A, tk); A.modal({ title: '🔔 New ticket auto-assigned to you', subtitle: `${tk.id} · ${A.O(tk.orgId).name} · acknowledge within ${A.D.routing.ackMinutes} min`, notes: [note(`${tk.title} — ${tk.type} · ${tk.module} ${tk.version} · ${tk.routedNote}`)].concat(sim.length ? [note(`Possible recurring issue — reported by ${new Set(sim.map(m => m.t.orgId).concat(tk.orgId)).size} clients.`, 'warn')] : []), lines: [{ text: 'Push notification (FCM/APNs) deep-links here. No client phone number or internal cost is included in the push.', style: 'font-size:11.5px;color:#8b8c90' }], actions: [{ label: 'Snooze 5 min', kind: 'secondary', onClick: () => { A.closeModal(); A.toast('Reminder in 5 min — SLA clock keeps running'); } }, { label: 'View ticket', kind: 'secondary', onClick: () => { A.closeModal(); A.go('ticketDetail', tk.id); } }, { label: 'Accept', kind: 'good', onClick: () => { A.closeModal(); if (tk.assignedTo === me.id || A.isMgr) { SUP.acceptTicket(A, tk.id); A.go('ticketDetail', tk.id); } else A.toast(`Only ${A.name(tk.assignedTo)} can accept — switch role to Developer`); } }] }); }

export function screens(A, ctx) {
  const { B, act, P, chip, kpi, setScr, tkItem } = ctx; const D = A.D, me = A.me;
  const status = (u) => { const av = D.availability[u.id]; if (av) return ['Absent', av.status + ' until ' + av.until, '#b3401f']; const oc = D.projects.filter(p => SUP.today(A, p.id) === u.id).map(p => p.name); const load = D.tickets.filter(t => t.assignedTo === u.id && !['RESOLVED', 'CLOSED'].includes(t.status)).length + D.tasks.filter(t => t.assignedTo === u.id && t.status === 'IN_PROGRESS').length; if (oc.length) return ['On-call', oc.join(', ') + ` · ${load} open`, '#3b5fa0']; if (load >= 6) return ['Busy', `${load} open items · near limit`, '#a06a10']; return ['Available', `${load} open items`, '#2f7a4a']; };
  return {
    team() { const devs = D.users.filter(u => ['developer', 'senior'].includes(u.role)); setScr({ title: 'Team availability', sub: 'Thu 04/09 · used by routing and IVR', blocks: [B.list(devs.map(u => { const [s, sub, c] = status(u); return { title: u.name, sub: `${u.title} · ${sub}`, pill: s, pillBg: c + '22', pillFg: c, dot: c, actions: A.isMgr ? [act(D.availability[u.id] ? 'Mark available' : 'Mark absent', 'secondary', () => { if (D.availability[u.id]) delete D.availability[u.id]; else D.availability[u.id] = { status: 'On leave', until: '05/09' }; A.audit('ADMIN', `${u.name} availability changed`); A.save(); }, null, true)] : [] }; })), B.list(D.oncall.slice(0, 5).map(d => ({ title: d.day, sub: D.projects.map(p => `${p.name}: ${d[p.id] && d[p.id] !== '—' ? A.name(d[p.id]) : '—'}`).join(' · ') })), { title: 'On-call schedule' }), A.isMgr ? B.text(['Change the rota, module owners and workload limits in Mobile admin or on desktop.'], { tone: 'warn' }) : null].filter(Boolean) }); },
    recurring() { const groups = {}; D.tickets.filter(t => D.routing.directTypes.includes(t.type)).forEach(t => { const k = `${A.P(t.projectId).name} · ${t.module} · ${t.version}`; (groups[k] = groups[k] || { n: 0, orgs: new Set(), prob: null }); groups[k].n++; groups[k].orgs.add(t.orgId); if (t.problemId) groups[k].prob = t.problemId; }); setScr({ title: 'Recurring issues', sub: 'by product · module · version', blocks: [B.list(Object.entries(groups).sort((a, b) => b[1].orgs.size - a[1].orgs.size).map(([k, g]) => ({ title: k, sub: `${g.n} tickets · ${g.orgs.size} client${g.orgs.size > 1 ? 's' : ''}${g.prob ? ' · ' + g.prob : ''}`, pill: g.orgs.size >= D.routing.threshold ? 'Recurring' : g.orgs.size > 1 ? 'Watch' : 'Single', pillBg: g.orgs.size >= D.routing.threshold ? '#fbe9e3' : g.orgs.size > 1 ? '#fbf1de' : '#ececea', pillFg: g.orgs.size >= D.routing.threshold ? '#b3401f' : g.orgs.size > 1 ? '#a06a10' : '#4a4b4e', onClick: g.prob ? P('problemDetail', g.prob) : () => A.toast('No problem record yet') })), { empty: 'No recurring issues.' }), B.actions([act('Problems / RCA', 'secondary', P('problems'))])] }); },
    adminMobile() { if (!A.isAdmin && !A.isMgr) return setScr({ title: 'Admin', blocks: [B.text(['Admin settings are available to Super Admin and Project Managers only.'], { tone: 'danger' })] }); const R = D.routing; const I = D.ivr; setScr({ title: 'Mobile admin', sub: 'Essentials only — advanced configuration on desktop', blocks: [B.list(D.projects.map(p => { const o = SUP.owner(A, p.id); return { title: p.name, sub: `Primary ${A.name(o.primary)} · backup ${A.name(o.backup)}${D.availability[o.backup] ? ' (absent)' : ''} · senior ${A.name(o.senior)} · modules: ${Object.keys(o.modules).join(', ')}`, onClick: () => MOD.editEntity(A, `Ownership · ${p.name}`, [{ key: 'primary', type: 'select', label: 'Primary developer', full: true, options: D.users.filter(u => ['developer', 'senior'].includes(u.role)).map(u => ({ value: u.id, label: u.name })), value: o.primary }, { key: 'backup', type: 'select', label: 'Backup developer', full: true, options: D.users.filter(u => ['developer', 'senior'].includes(u.role)).map(u => ({ value: u.id, label: u.name })), value: o.backup }], g => { o.primary = g('primary'); o.backup = g('backup'); A.audit('ADMIN', `Ownership updated · ${p.name}`); }) }; }), { title: 'Primary / backup mapping & module ownership' }), B.kv([['Acknowledge within', `${R.ackMinutes} min`], ['Escalate to senior', `${R.escalationMinutes} min`], ['Duplicate threshold', `${R.threshold} clients`], ['Direct-to-developer', R.directTypes.join(', ')]], { title: 'SLA & escalation rules', link: 'Edit', linkClick: () => MOD.editEntity(A, 'Rules', [{ key: 'a', type: 'text', label: 'Acknowledge within (min)', value: String(R.ackMinutes) }, { key: 'e', type: 'text', label: 'Escalate to senior (min)', value: String(R.escalationMinutes) }, { key: 't', type: 'text', label: 'Duplicate threshold', value: String(R.threshold) }], g => { R.ackMinutes = +g('a') || R.ackMinutes; R.escalationMinutes = +g('e') || R.escalationMinutes; R.threshold = +g('t') || R.threshold; }) }), B.kv([['Routing', `${D.tickets.filter(t => ['AUTO_ASSIGNED', 'ESCALATED'].includes(t.status)).length} awaiting ack · ${D.tickets.filter(t => t.escalationLevel > 0 && !['RESOLVED', 'CLOSED'].includes(t.status)).length} escalated`], ['IVR', `${I.provider} · ${I.status} · ${I.webhooks24h} events/24h`, 'green'], ['Callback queue', String(D.callbacks.filter(c => c.status !== 'Done').length)], ['Absent developers', Object.keys(D.availability).map(u => A.name(u)).join(', ') || 'none']], { title: 'Routing status & IVR health' }), B.actions([act('Team availability & on-call', 'secondary', P('team')), act('SLA & escalations', 'secondary', P('sla')), act('Simulate incoming IVR call', 'secondary', () => SUP.simulateInbound(A))])] }); },
  };
}
